def run(input):
    import json, os, subprocess
    json.dump(input, open(input['run_dir'] + '/node-input.json', 'w'))
    r = subprocess.run(['python3', input['engine'], 'step', input['step'], '--run-dir', input['run_dir']], capture_output=True, text=True, timeout=input.get('sub_timeout', 3600), env=dict(os.environ, SELF_IMPROVE_RUN_DIR=input['run_dir']))
    if r.returncode != 0: raise RuntimeError('engine step ' + input['step'] + ' failed: ' + (r.stderr or r.stdout or '')[-800:])
    return json.load(open(input['run_dir'] + '/step-result.json'))

